uiRules.userScript:
(() => {
  const BUTTON_ID = "centrix-new-chat";
  const STYLE_ID = "centrix-new-chat-style";

  function addStyles() {
    let style = document.getElementById(STYLE_ID);

    if (!style) {
      style = document.createElement("style");
      style.id = STYLE_ID;
      document.head.appendChild(style);
    }

    style.textContent = `
      #centrix-new-chat {
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        flex-shrink: 0 !important;
        gap: 6px !important;

        height: 34px !important;
        padding: 0 12px !important;
        margin-right: 4px !important;

        border: 1px solid var(--border-300, rgba(127,127,127,.25)) !important;
        border-radius: 9px !important;

        background: var(--bg-100, rgba(127,127,127,.08)) !important;
        color: var(--text-100, #ffffff) !important;

        font-family: inherit !important;
        font-size: 14px !important;
        font-weight: 500 !important;
        line-height: 1 !important;

        text-decoration: none !important;
        cursor: pointer !important;
        position: relative !important;
        z-index: 20 !important;

        transition:
          background-color .15s ease,
          border-color .15s ease !important;
      }

      #centrix-new-chat:hover {
        background: var(--bg-200, rgba(127,127,127,.16)) !important;
        border-color: var(--border-200, rgba(127,127,127,.4)) !important;
      }

      #centrix-new-chat .centrix-new-chat-icon {
        display: inline-flex !important;
        align-items: center !important;
        justify-content: center !important;
        font-size: 19px !important;
        line-height: 1 !important;
      }

      #centrix-new-chat .centrix-new-chat-label {
        white-space: nowrap !important;
      }

      @media (max-width: 600px) {
        #centrix-new-chat {
          width: 34px !important;
          padding: 0 !important;
        }

        #centrix-new-chat .centrix-new-chat-label {
          display: none !important;
        }
      }
    `;
  }

  function mountButton() {
    const target = document.querySelector(
      "#dframe-header-actions-slot"
    );

    if (!target) return;

    let button = document.getElementById(BUTTON_ID);

    if (!button) {
      button = document.createElement("a");
      button.id = BUTTON_ID;
      button.href = "/new";
      button.setAttribute("aria-label", "New chat");

      button.innerHTML = `
        <span class="centrix-new-chat-icon">＋</span>
        <span class="centrix-new-chat-label">New chat</span>
      `;
    }

    if (button.parentElement !== target) {
      target.prepend(button);
    }
  }

  addStyles();
  mountButton();

  new MutationObserver(mountButton).observe(document.body, {
    childList: true,
    subtree: true
  });
})();

